import { ComparisonTable } from '@refy-design/web';
import type { ComponentProps } from 'react';
export function Example() {
  const args: Pick<
    ComponentProps<typeof ComparisonTable>,
    'caption' | 'options' | 'highlight' | 'rows'
  > = {
    caption: 'Plan comparison',
    options: ['Starter', 'Team', 'Business'],
    highlight: 1,
    rows: [
      { feature: 'Price per month', values: ['Free', '$ 12', '$ 29'] },
      { feature: 'Projects', values: ['3', 'Unlimited', 'Unlimited'] },
      { feature: 'Custom theme', values: [false, true, true] },
      {
        feature: 'Single sign-on',
        hint: 'SAML and OIDC',
        values: [false, false, true],
      },
      { feature: 'Support', values: ['Community', 'Email', 'Priority'] },
    ],
  };
  return <ComparisonTable {...args} />;
}

